import{_ as p,a0 as l,w as o,s as d,ao as r,I as i,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"PyLint 的優點、缺點和危險 | LCTT x X-CMD","titleTemplate":false,"description":"PyLint 的優點、缺點和危險 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PyLint 的優點、缺點和危險 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PyLint 的優點、缺點和危險 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220919 PyLint- The good, the bad, and the ugly","title":"PyLint 的優點、缺點和危險","tag":"202210","desc":""},"relativePath":"202210/20220919 PyLint- The good, the bad, and the ugly.md","filePath":"[post].md"}'),h={name:"202210/20220919 PyLint- The good, the bad, and the ugly.md"};function c(u,s,g,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="pylint-的優點、缺點和危險" tabindex="-1">PyLint 的優點、缺點和危險 <a class="header-anchor" href="#pylint-的優點、缺點和危險" aria-label="Permalink to “PyLint 的優點、缺點和危險”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/16/093840z9pnzfv9ykfccoq9.jpg" alt=""></p><blockquote><p>充分利用 PyLint。</p></blockquote><p>敲黑板：PyLint 實際上很好！</p><p>“PyLint 可以拯救你的生命”，這是一句誇張的描述，但沒有你想像的那麼誇張。PyLint 可以讓你遠離非常難找到的和複雜的缺陷。最差的情況下，它只可以節省測試運行的時間。最好的情況下，它可以幫你避免生產環境中複雜的錯誤。</p><h3 id="優點" tabindex="-1">優點 <a class="header-anchor" href="#優點" aria-label="Permalink to “優點”">​</a></h3><p>我不好意思説這種情況是多麼普遍。測試的命名總是<em>那麼奇怪</em>：沒有人關心這個名稱，而且通常也找不到一個自然的名稱。例如以下代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def test_add_small():</span></span>
<span class="line"><span>    # Math, am I right?</span></span>
<span class="line"><span>    assert 1 + 1 == 3</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>def test_add_large():</span></span>
<span class="line"><span>    assert 5 + 6 == 11</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>def test_add_small():</span></span>
<span class="line"><span>    assert 1 + 10 == 11</span></span></code></pre></div><p>測試生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>collected 2 items                                                                         </span></span>
<span class="line"><span>test.py .. </span></span>
<span class="line"><span>2 passed</span></span></code></pre></div><p>但問題是：如果你覆蓋了一個測試的名稱，測試框架將愉快地跳過這個測試！</p><p>實際上，這些文件可能有數百行，而添加新測試的人可能並不知道所有的名稱。除非有人仔細查看測試輸出，否則一切看起來都很好。</p><p>最糟糕的是，<em>被覆蓋測試的添加</em>、<em>被覆蓋測試造成的破壞</em>，以及<em>連鎖反應的問題</em>可能要幾天、幾月甚至幾年才能發現。</p><h3 id="pylint-會找到它" tabindex="-1">PyLint 會找到它 <a class="header-anchor" href="#pylint-會找到它" aria-label="Permalink to “PyLint 會找到它”">​</a></h3><p>就像一個好朋友一樣，PyLint 可以幫助你。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test.py:8:0: E0102: function already defined line 1</span></span>
<span class="line"><span>     (function-redefined)</span></span></code></pre></div><h3 id="缺點" tabindex="-1">缺點 <a class="header-anchor" href="#缺點" aria-label="Permalink to “缺點”">​</a></h3><p>就像 90 年代的情景喜劇一樣，你對 PyLint 瞭解的越多，問題就越多。以下是一個庫存建模程序的常規代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;&quot;&quot;Inventory abstractions&quot;&quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import attrs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@attrs.define</span></span>
<span class="line"><span>class Laptop:</span></span>
<span class="line"><span>    &quot;&quot;&quot;A laptop&quot;&quot;&quot;</span></span>
<span class="line"><span>    ident: str</span></span>
<span class="line"><span>    cpu: str</span></span></code></pre></div><p>但 PyLint 似乎有自己的觀點（可能形成於 90 年代），並且不怕把它們作為事實陳述出來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pylint laptop.py | sed -n &#39;/^laptop/s/[^ ]*: //p&#39;</span></span>
<span class="line"><span>R0903: Too few public methods (0/2) (too-few-public-methods)</span></span></code></pre></div><h3 id="危險" tabindex="-1">危險 <a class="header-anchor" href="#危險" aria-label="Permalink to “危險”">​</a></h3><p>有沒有想過在一個數百萬人使用的工具中加入自己未證實的觀點？PyLint 每月有 1200 萬次下載。</p><blockquote><p>“如果太挑剔，人們會取消檢查” — 這是 PyLint GitHub 的 6987 號議題，於 2022 年 7 月 3 號提出</p></blockquote><p>對於添加一個可能有許多誤報的測試，它的態度是 ... “<em>嗯</em>”。</p><h3 id="讓它為你工作" tabindex="-1">讓它為你工作 <a class="header-anchor" href="#讓它為你工作" aria-label="Permalink to “讓它為你工作”">​</a></h3><p>PyLint 很好，但你需要小心地與它配合。為了讓 PyLint 為你工作，以下是我推薦的三件事：</p><h4 id="_1、固定版本" tabindex="-1">1、固定版本 <a class="header-anchor" href="#_1、固定版本" aria-label="Permalink to “1、固定版本”">​</a></h4><p>固定你使用的 PyLint 版本，避免任何驚喜！</p><p>在你的 <code>.toml</code> 文件中定義:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[project.optional-dependencies]</span></span>
<span class="line"><span>pylint = [&quot;pylint&quot;]</span></span></code></pre></div><p>在代碼中定義：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from unittest import mock</span></span></code></pre></div><p>這與以下代碼對應：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># noxfile.py</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>@nox.session(python=VERSIONS[-1])</span></span>
<span class="line"><span>def refresh_deps(session):</span></span>
<span class="line"><span>    &quot;&quot;&quot;Refresh the requirements-*.txt files&quot;&quot;&quot;</span></span>
<span class="line"><span>    session.install(&quot;pip-tools&quot;)</span></span>
<span class="line"><span>    for deps in [..., &quot;pylint&quot;]:</span></span>
<span class="line"><span>        session.run(</span></span>
<span class="line"><span>            &quot;pip-compile&quot;,</span></span>
<span class="line"><span>            &quot;--extra&quot;,</span></span>
<span class="line"><span>            deps,</span></span>
<span class="line"><span>            &quot;pyproject.toml&quot;,</span></span>
<span class="line"><span>            &quot;--output-file&quot;,</span></span>
<span class="line"><span>            f&quot;requirements-{deps}.txt&quot;,</span></span>
<span class="line"><span>        )</span></span></code></pre></div><h4 id="_2、默認禁止" tabindex="-1">2、默認禁止 <a class="header-anchor" href="#_2、默認禁止" aria-label="Permalink to “2、默認禁止”">​</a></h4><p>禁用所有檢查，然後啓用那些你認為誤報比率高的。（不僅僅是漏報/誤報的比率！）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># noxfile.py</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>@nox.session(python=&quot;3.10&quot;)</span></span>
<span class="line"><span>def lint(session):</span></span>
<span class="line"><span>    files = [&quot;src/&quot;, &quot;noxfile.py&quot;]</span></span>
<span class="line"><span>    session.install(&quot;-r&quot;, &quot;requirements-pylint.txt&quot;)</span></span>
<span class="line"><span>    session.install(&quot;-e&quot;, &quot;.&quot;)</span></span>
<span class="line"><span>    session.run(</span></span>
<span class="line"><span>        &quot;pylint&quot;,</span></span>
<span class="line"><span>        &quot;--disable=all&quot;,</span></span>
<span class="line"><span>        *(f&quot;--enable={checker}&quot; for checker in checkers)</span></span>
<span class="line"><span>        &quot;src&quot;,</span></span>
<span class="line"><span>    )</span></span></code></pre></div><h4 id="_3、檢查器" tabindex="-1">3、檢查器 <a class="header-anchor" href="#_3、檢查器" aria-label="Permalink to “3、檢查器”">​</a></h4><p>以下是我喜歡的檢查器。加強項目的一致性，避免一些明顯的錯誤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>checkers = [</span></span>
<span class="line"><span>    &quot;missing-class-docstring&quot;,</span></span>
<span class="line"><span>    &quot;missing-function-docstring&quot;,</span></span>
<span class="line"><span>    &quot;missing-module-docstring&quot;,</span></span>
<span class="line"><span>    &quot;function-redefined&quot;,</span></span>
<span class="line"><span>]</span></span></code></pre></div><h3 id="使用-pylint" tabindex="-1">使用 PyLint <a class="header-anchor" href="#使用-pylint" aria-label="Permalink to “使用 PyLint”">​</a></h3><p>你可以只使用 PyLint 好的部分。在 CI 中運行它以保持一致性，並使用常用檢查器。</p><p>放棄不好的部分：默認禁止檢查器。</p><p>避免危險的部分：固定版本以避免意外。</p><hr>`,46)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/22/9/pylint-good-bad-ugly"},{default:t(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/22/9/pylint-good-bad-ugly",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lkxed"},{default:t(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[4]||(s[4]=[a("MjSeven",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const x=p(h,[["render",c]]);export{q as __pageData,x as default};
